-- Project 3 — version-controlled analytical views
-- Generated by python/preparation/create_sql_analytical_views.py.
-- Source SQLite database is local/generated and is not committed to Git.

DROP VIEW IF EXISTS vw_Annual_Production_Summary;
DROP VIEW IF EXISTS vw_Annual_Economics_Summary;
DROP VIEW IF EXISTS vw_Base_Investment_Comparison;
DROP VIEW IF EXISTS vw_Scenario_Investment_Comparison;
DROP VIEW IF EXISTS vw_Scenario_NPV_Comparison;
DROP VIEW IF EXISTS vw_Scenario_Cash_Flow_Profile;

CREATE VIEW vw_Annual_Production_Summary AS
SELECT "Development_Concept" AS Development_Concept,
       "Project_Year" AS Project_Year,
       "Annual_Oil_Production_bbl" AS Annual_Oil_Production_bbl,
       SUM("Annual_Oil_Production_bbl") OVER (PARTITION BY "Development_Concept" ORDER BY "Project_Year"
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS Cumulative_Oil_Production_bbl
FROM "Fact_Annual_Production";

CREATE VIEW vw_Annual_Economics_Summary AS SELECT * FROM "Fact_Annual_Economics";
CREATE VIEW vw_Base_Investment_Comparison AS SELECT * FROM "Fact_Investment_Metrics";
CREATE VIEW vw_Scenario_Investment_Comparison AS SELECT * FROM "Fact_Scenario_Investment_Metrics";

CREATE VIEW vw_Scenario_NPV_Comparison AS
SELECT "Development_Concept" AS Development_Concept,
       MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('low','low price') THEN "NPV_USD" END) AS NPV_Low_USD,
       MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('base','base price') THEN "NPV_USD" END) AS NPV_Base_USD,
       MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('high','high price') THEN "NPV_USD" END) AS NPV_High_USD,
       MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('low','low price') THEN "NPV_USD" END)
         - MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('base','base price') THEN "NPV_USD" END) AS NPV_Low_vs_Base_USD,
       MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('high','high price') THEN "NPV_USD" END)
         - MAX(CASE WHEN lower("Oil_Price_Scenario") IN ('base','base price') THEN "NPV_USD" END) AS NPV_High_vs_Base_USD
FROM "Fact_Scenario_Investment_Metrics" GROUP BY "Development_Concept";

CREATE VIEW vw_Scenario_Cash_Flow_Profile AS
SELECT se."Development_Concept" AS Development_Concept,
       se."Oil_Price_Scenario" AS Oil_Price_Scenario,
       se."Project_Year" AS Project_Year,
       se."Net_Project_Cash_Flow_USD" AS Net_Cash_Flow_USD,
       sd."Discounted_Cash_Flow_USD" AS Discounted_Cash_Flow_USD
FROM "Fact_Scenario_Annual_Economics" se
INNER JOIN "Fact_Scenario_Discounted_Cash_Flow" sd
 ON se."Development_Concept" = sd."Development_Concept"
AND se."Oil_Price_Scenario" = sd."Oil_Price_Scenario"
AND se."Project_Year" = sd."Project_Year";
